"""Dump every object in report.pdf to understand its structure."""
import re

with open("report.pdf", "rb") as f:
    data = f.read()

# Parse xref: find all "N 0 obj" at their byte offsets
objects = {}
for m in re.finditer(rb"(\d+)\s+(\d+)\s+obj", data):
    num = int(m.group(1))
    start = m.start()
    # find endobj
    end = data.find(b"endobj", start)
    if end == -1:
        end = len(data)
    objects[num] = data[start:end + len(b"endobj")]

for num in sorted(objects):
    print(f"===== Object {num} =====")
    print(objects[num].decode("latin-1"))
    print()

